import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Chapitre 106 | Affinement du Royaume · Royaume de la Perception Originelle · Comparaison entre le Camp Prédateur et le Camp Symbiotique","description":"","frontmatter":{"title":"Chapitre 106 | Affinement du Royaume · Royaume de la Perception Originelle · Comparaison entre le Camp Prédateur et le Camp Symbiotique","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","路线对比"],"related":["04-掠夺式修炼体系批判","01-衡元宙核心世界观","14-修炼境界统一划分"]},"headers":[],"relativePath":"fr/106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"fr/106_模块1-感元境-掠夺派vs共生派对比.md"}'),s={name:"fr/106_模块1-感元境-掠夺派vs共生派对比.md"};function l(u,e,n,o,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="chapitre-106-royaume-de-la-perception-originelle-comparaison-systemique-entre-le-camp-predateur-et-le-camp-symbiotique" tabindex="-1">Chapitre 106 | Royaume de la Perception Originelle : comparaison systémique entre le camp prédateur et le camp symbiotique <a class="header-anchor" href="#chapitre-106-royaume-de-la-perception-originelle-comparaison-systemique-entre-le-camp-predateur-et-le-camp-symbiotique" aria-label="Permalink to &quot;Chapitre 106 | Royaume de la Perception Originelle : comparaison systémique entre le camp prédateur et le camp symbiotique&quot;">​</a></h1><blockquote><p>Module : Module un · Affinement approfondi des royaumes | Documents de référence : 04, 01, 14</p></blockquote><h2 id="introduction-deux-logiques-de-culture-deux-sortes-d-univers" tabindex="-1">Introduction : deux logiques de culture, deux sortes d&#39;univers <a class="header-anchor" href="#introduction-deux-logiques-de-culture-deux-sortes-d-univers" aria-label="Permalink to &quot;Introduction : deux logiques de culture, deux sortes d&#39;univers&quot;">​</a></h2><p>Le Royaume de la Perception Originelle n&#39;est pas seulement le point de départ de la culture, mais aussi le tout premier carrefour de la vision du monde : dès la toute première absorption d&#39;énergie, le cultivateur se tient déjà à la fourche — soit « je prends au monde », soit « je croisis avec le monde ». Ces deux phrases paraissent proches, mais elles mènent à deux univers entièrement différents : l&#39;un est un champ de chasse où le fort mange le faible ; l&#39;autre est une communauté de vie où tous les êtres s&#39;élèvent ensemble.</p><p>Cet article donne la comparaison au niveau systémique entre le Système de Culture Prédatrice et la Civilisation Symbiotique de l&#39;Ancre.</p><p>Les Six Axiomes Suprêmes sont la ligne de partage elle-même : l&#39;Axiome de l&#39;Anti-Prédateur sépare « prendre » de « croître » ; l&#39;Axiome de la République des Dix Mille Races sépare « ma race seule » de « toutes les races » ; l&#39;Axiome de l&#39;Ascension Dimensionnelle Collective sépare « je m&#39;élève seul » de « nous nous élevons ensemble » ; l&#39;Axiome de l&#39;Autodiscipline Causale sépare « la dette ailleurs » de « je porte mon propre fruit » ; l&#39;Axiome de la Priorité de la Loi sépare « des règles à ma convenance » de « une loi stable et cohérente ». La Loi d&#39;Égalité Infinie Universelle pour tous les Êtres établit que tout être porte en soi le Pouvoir Infini Fondamental : les nonchalants conservent un infini plancher garanti et ne sont pas éliminés par les temps, tandis que les acharnés et les jeunes suprêmes peuvent empiler des degrés supérieurs d&#39;infini. L&#39;origine infinie est portée par tous — la logique prédatrice de « seuls les forts peuvent survivre » est déjà invalide sur son visage.</p><h2 id="i-tableau-maitre-de-la-comparaison-systemique" tabindex="-1">I. Tableau maître de la comparaison systémique <a class="header-anchor" href="#i-tableau-maitre-de-la-comparaison-systemique" aria-label="Permalink to &quot;I. Tableau maître de la comparaison systémique&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Camp prédateur</th><th>Camp symbiotique (Ancre)</th></tr></thead><tbody><tr><td>Source d&#39;énergie</td><td>Dévore l&#39;origine d&#39;autrui</td><td>Prend au cycle du monde, rend en retour</td></tr><tr><td>Attitude envers les faibles</td><td>Élimination naturelle, meurs si faible</td><td>Garde-fou pour tous, pas un de moins</td></tr><tr><td>Logique du plafond</td><td>Un sommet sur un cimetière</td><td>Le tout s&#39;élève ensemble</td></tr><tr><td>Horizon temporel</td><td>Draine maintenant, jette plus tard</td><td>Double cycle, durable</td></tr><tr><td>Attitude envers le risque</td><td>Le risque est un filtre</td><td>Le risque est un problème à gérer</td></tr><tr><td>Base éthique</td><td>La force fait le droit</td><td>Autodiscipline causale</td></tr><tr><td>Destination ultime</td><td>Le suzerain d&#39;un seul secteur stellaire</td><td>Royaume de l&#39;Ancre Équilibrée Hyper-Pluraliste</td></tr></tbody></table><h2 id="ii-les-trois-erreurs-du-camp-predateur" tabindex="-1">II. Les trois erreurs du camp prédateur <a class="header-anchor" href="#ii-les-trois-erreurs-du-camp-predateur" aria-label="Permalink to &quot;II. Les trois erreurs du camp prédateur&quot;">​</a></h2><ol><li>Erreur du jeu à somme nulle : il croit que la puissance est fixe, donc pour la gagner il faut prendre à autrui — aveugle au fait que l&#39;énergie du cycle du monde est renouvelable et expansive.</li><li>Erreur de l&#39;élimination naturelle : il croit que les faibles méritent d&#39;être éliminés — aveugle au fait que l&#39;infini plancher des nonchalants laisse les lents suivre sans être écrasés.</li><li>Erreur du « prédateur éclairé » : il croit qu&#39;un prédateur bienveillant est le meilleur prédateur — aveugle au fait que la structure même de la prédation est la maladie, non le tempérament du prédateur.</li></ol><h2 id="iii-le-«-predateur-eclaire-»-et-la-regression-historique" tabindex="-1">III. Le « prédateur éclairé » et la régression historique <a class="header-anchor" href="#iii-le-«-predateur-eclaire-»-et-la-regression-historique" aria-label="Permalink to &quot;III. Le « prédateur éclairé » et la régression historique&quot;">​</a></h2><p>Le soi-disant prédateur éclairé — c&#39;est-à-dire le fort qui ne tue pas sans motif, qui « partage un peu » avec les faibles, qui se dit bienveillant — est l&#39;auto-illusion la plus dangereuse du camp prédateur. Un chasseur aimable est encore un chasseur ; sa bienveillance n&#39;est que l&#39;affinement de sa gestion du gibier. L&#39;histoire montre maintes fois que l&#39;ère « éclairée » d&#39;un système prédateur est toujours la veille de la régression : une fois les champs de chasse épuisés, les forts « bienveillants » sont les premiers à se tourner contre leurs propres gens.</p><h2 id="iv-le-gredin-juste-un-avertissement-aux-«-elus-»" tabindex="-1">IV. Le gredin juste : un avertissement aux « élus » <a class="header-anchor" href="#iv-le-gredin-juste-un-avertissement-aux-«-elus-»" aria-label="Permalink to &quot;IV. Le gredin juste : un avertissement aux « élus »&quot;">​</a></h2><p>Le camp symbiotique ne prétend pas que son propre camp est parfait. La variante la plus insidieuse est le « gredin juste » : celui qui revêt le manteau de la justice pour piller encore, qui dit « je fais cela pour la symbiose » tout en drainant autrui pour sa propre percée.</p><p>Prenons Lin Hao, le protagoniste de cet univers, comme pierre de touche : sa voie n&#39;est pas de devenir le plus fort d&#39;un champ de chasse, mais de prouver que le fort peut s&#39;élever tout en laissant aux faibles un chemin de retour. Chaque fois qu&#39;il est tenté de dire « je suis spécial, donc les règles ne s&#39;appliquent pas à moi », c&#39;est le moment précis où le Démon intérieur du Raccourci frappe — c&#39;est la ligne intérieure que tout cultivateur du camp symbiotique doit tenir.</p><h2 id="v-cinq-points-d-ancrage-essentiels" tabindex="-1">V. Cinq points d&#39;ancrage essentiels <a class="header-anchor" href="#v-cinq-points-d-ancrage-essentiels" aria-label="Permalink to &quot;V. Cinq points d&#39;ancrage essentiels&quot;">​</a></h2><ul><li>Anti-gaspillage de grade énergétique : le « fort mange le faible » du camp prédateur gaspille plus de potentiel évolutif que toute guerre ; le double cycle du camp symbiotique est la vraie haute efficacité.</li><li>Anti-prédation : chaque ligne du tableau maître est une ligne rouge que le camp symbiotique ne franchira pas.</li><li>Comparaison au plafond de Tang Luo : le plafond du camp prédateur est un suzerain sur un cimetière ; le plafond du camp symbiotique soulève tout le cosmos.</li><li>Couverture totale des Dix Mille Races : le tableau maître couvre toute dimension, de la source d&#39;énergie à la destination ultime, sans angle mort.</li><li>Ouverture totale hyper-pluraliste : la comparaison elle-même est une preuve ouverte — le camp prédateur n&#39;ose pas la publier, car chaque dimension expose sa propre petitesse.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Un tableau n&#39;a pas besoin de rhétorique ; les deux colonnes parlent déjà. Au Royaume de la Perception Originelle, la première absorption que le cultivateur choisit décide dans quelle colonne il se tiendra pour le reste de sa vie — c&#39;est pourquoi cette comparaison est placée tout au début de toute la bibliothèque : que chaque lecteur voie, avant de choisir la voie, dans quel univers il s&#39;apprête à entrer.</p><h2 id="liens" tabindex="-1">Liens <a class="header-anchor" href="#liens" aria-label="Permalink to &quot;Liens&quot;">​</a></h2><ul><li>Documents liés : <a href="./04-掠夺式修炼体系批判.html">04-Critique du Système de Culture Prédatrice</a> · <a href="./01-衡元宙核心世界观.html">01-Vision du monde fondamentale de Heng Yuan Zhou</a> · <a href="./14-修炼境界统一划分.html">14-Classification unifiée des royaumes de culture</a></li><li>Site officiel : <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',21)])])}const h=t(s,[["render",l]]);export{m as __pageData,h as default};
